import sys


def base36_increment(s: str) -> str:
    """Increment a base-36 string (0-9, A-Z) by 1."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        c = chars[i]
        if "0" <= c <= "9":
            if c == "9":
                chars[i] = "A"
                return "".join(chars)
            chars[i] = chr(ord(c) + 1)
            return "".join(chars)
        elif "A" <= c <= "Z":
            if c == "Z":
                chars[i] = "0"
                continue  # carry over
            chars[i] = chr(ord(c) + 1)
            return "".join(chars)
        else:
            raise ValueError(f"Unexpected character: {c}")
    # Overflow: all characters wrapped around
    return "0" * len(s)


def main() -> None:
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        # No IDs yet, start from the beginning
        print("ORD-0000")
        return

    last_id = lines[-1]
    # Expected format: ORD-XXXX
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"Unexpected ID format: {last_id}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    next_suffix = base36_increment(suffix)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

