import sys

def base36_encode(n):
    """Encode an integer as base36 string."""
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if n == 0:
        return chars[0]
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    return ''.join(reversed(result))

def base36_decode(s):
    """Decode a base36 string to an integer."""
    return int(s, 36)

